"""Leap-year functions used by the grader. Do not edit this file.

`correct` follows the Gregorian rule. The others each contain one bug.
"""


def correct(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def bug_only_four(year):
    return year % 4 == 0


def bug_forgets_400(year):
    return year % 4 == 0 and year % 100 != 0


def bug_century_always_leap(year):
    return year % 4 == 0 and year % 100 != 0 or year % 100 == 0


def bug_200_rule(year):
    return year % 4 == 0 and year % 100 != 0 or year % 200 == 0


def bug_1000_rule(year):
    return year % 4 == 0 and year % 100 != 0 or year % 1000 == 0


def bug_off_by_one(year):
    return (year + 1) % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
